/***************************   Cloning   ******************************/

Unit clone_Unit(Unit p)
{
  switch(p->kind)
  {
  case is_UUnit:
    return make_UUnit
      ( strdup(p->u.uUnit_.decimal_)
      , clone_Form(p->u.uUnit_.form_)
      , strdup(p->u.uUnit_.jsonstring_)
      , clone_ListDeclaration(p->u.uUnit_.listdeclaration_)
      );

  default:
    fprintf(stderr, "Error: bad kind field when cloning Unit!\n");
    exit(1);
  }
}

