{
  switch(p->kind)
  {
  case is_FCfg:
    return make_FCfg ();

  case is_FSsa:
    return make_FSsa ();

  case is_FFunctional:
    return make_FFunctional ();

  default:
    fprintf(stderr, "Error: bad kind field when cloning Form!\n");
    exit(1);
  }
}

