  case is_DFunction:
    return make_DFunction
      ( strdup(p->u.dFunction_.callablename_)
      , clone_Parameters(p->u.dFunction_.parameters_)
      , clone_Type(p->u.dFunction_.type_)
      , clone_Body(p->u.dFunction_.body_)
      );

  case is_DRoutine:
